declaration:
FUNCTION_BLOCK FB

VAR_INPUT
    enable : BOOL;
    values : ARRAY[1..8] OF INT;
    count : INT;
    avgEnable : BOOL;
END_VAR
VAR_OUTPUT
    avgOut : REAL;
END_VAR
VAR
    i : INT;
    n : INT;
    sum : DINT;
    keep : REAL;
END_VAR

implementation:
n := count;
IF n < 0 THEN
    n := 0;
ELSIF n > 8 THEN
    n := 8;
END_IF


IF enable AND avgEnable AND n > 0 THEN
    sum := 0;
    FOR i := 1 TO n DO
        sum := sum + values[i];
    END_FOR
    keep := DINT_TO_REAL(sum) / INT_TO_REAL(n);
END_IF
avgOut := keep;
